function closestHold(x,y,maxY=2){let best=null,score=1e9;for(const h of holds){const dy=Math.abs(h.y-y),dx=Math.abs(h.x-x);const s=dy*1.6+dx;if(dy<maxY&&s<score){score=s;best=h}}return best}
player.handTargets=[closestHold(-.5,2.1),closestHold(.5,2.1)];
const targetRing=new THREE.Mesh(new THREE.TorusGeometry(.34,.035,7,24),new THREE.MeshBasicMaterial({color:0xffe2a2,transparent:true,opacity:.9}));targetRing.rotation.x=0;targetRing.position.z=-.66;scene.add(targetRing);
