function pose(){climber.position.set(player.x,player.y,.42);const bob=player.started&&!player.finished&&player.resting?Math.sin(performance.now()*.002)*.025:0;
 const shoulders=[new THREE.Vector3(-.29,.40+bob,.02),new THREE.Vector3(.29,.40+bob,.02)];
 for(let i=0;i<2;i++){let h=player.handTargets[i];let hand=h?new THREE.Vector3(h.x-player.x,h.y-player.y,-1.03):new THREE.Vector3(i?0.65:-.65,.85,-.8);hand.y+=Math.sin(performance.now()*.006+i)*.025;const elbow=new THREE.Vector3((shoulders[i].x+hand.x)*.53,(shoulders[i].y+hand.y)*.5,-.35);limbBetween(i?upperR:upperL,shoulders[i],elbow);limbBetween(i?foreR:foreL,elbow,hand);(i?handR:handL).position.copy(hand);(i?handR:handL).scale.set(1,.9,.72)}
 const hips=[new THREE.Vector3(-.2,-.55,.02),new THREE.Vector3(.2,-.55,.02)];for(let i=0;i<2;i++){const knee=new THREE.Vector3(hips[i].x+(i?-.16:.18),-.99+(i?-.08:.04),-.02);const foot=new THREE.Vector3(hips[i].x+(i?-.34:.32),-1.42+(i?-.06:.04),-.18);limbBetween(i?legR:legL,hips[i],knee);(i?bootR:bootL).position.copy(foot);limbBetween(i?legR:legL,knee,foot)}
}
function updateTarget(){const h=closestHold(player.x,player.y+1.3,1.3);if(h){targetRing.position.set(h.x,h.y,-.64);targetDot.position.set(h.x,h.y,-.61);targetRing.visible=true;targetDot.visible=true}else{targetRing.visible=false;targetDot.visible=false}}
const gripText=document.querySelector('#grip'),timerText=document.querySelector('#timer'),progress=document.querySelector('#progress'),percent=document.querySelector('#percent'),msg=document.querySelector('#message');let messageTimer=0;
function tell(text){msg.textContent=text;msg.classList.add('show');clearTimeout(messageTimer);messageTimer=setTimeout(()=>msg.classList.remove('show'),1550)}
function updateHud(){const pct=Math.min(100,Math.max(0,Math.round((player.y-1.1)/(28-1.1)*100)));progress.style.width=pct+'%';percent.textContent=pct+'%';gripText.textContent=Math.round(player.grip);gripText.style.color=player.grip<25?'#ff8e72':'';const sec=Math.floor(player.elapsed),m=String(Math.floor(sec/60)).padStart(2,'0'),s=String(sec%60).padStart(2,'0');timerText.textContent=`${m}:${s}`}
