function move(dir){if(!player.started||player.finished)return;const next=THREE.MathUtils.clamp(player.x+dir*.58,-5.3,5.3);if(Math.abs(next-player.x)<.05)return;player.x=next;player.grip=Math.max(0,player.grip-2.5);player.reach=dir;const h=closestHold(player.x+(dir*.28),player.y+1.12,1.2);if(h)player.handTargets[dir<0?0:1]=h;pose();updateTarget();updateHud();if(player.grip<=0)slip()}
