window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.repeat)return;switch(e.key.toLowerCase()){case'w':case'arrowup':case' ':climb();break;case'a':case'arrowleft':move(-1);break;case'd':case'arrowright':move(1);break;case's':rest(true);break}});window.addEventListener('keyup',e=>{if(e.key.toLowerCase()==='s')rest(false)});
// Tap a glowing rock to make a deliberate reach when it is within range.
renderer.domElement.addEventListener('pointerdown',e=>{if(!player.started||player.finished)return;const rect=renderer.domElement.getBoundingClientRect();const pointer=new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-((e.clientY-rect.top)/rect.height)*2+1);const ray=new THREE.Raycaster();ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(holds.map(h=>h.mesh),false)[0];if(hit){const hold=holds.find(h=>h.mesh===hit.object);if(hold&&hold.y>player.y-.2&&hold.y<player.y+2.1&&Math.abs(hold.x-player.x)<2.5){const cost=5+Math.abs(hold.x-player.x)*2;if(player.grip>=cost){player.grip-=cost;player.handTargets[player.climbs%2]=hold;player.reach=hold.x-player.x;pose();updateHud();tell('GOOD HOLD');}else slip()}}});
function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<620?55:48;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))}window.addEventListener('resize',resize);
const clock=new THREE.Clock();function tick(){requestAnimationFrame(tick);const dt=Math.min(clock.getDelta(),.05);if(player.started&&!player.finished){player.elapsed+=dt;if(player.resting)player.grip=Math.min(100,player.grip+dt*13);else if(player.grip<100)player.grip=Math.min(100,player.grip+dt*.45);updateHud()}
 const targetY=player.y+1.55;camera.position.x=THREE.MathUtils.damp(camera.position.x,player.x*.28,1.8,dt);camera.position.y=THREE.MathUtils.damp(camera.position.y,targetY+4.7,1.25,dt);camera.position.z=THREE.MathUtils.damp(camera.position.z,17,1.3,dt);camera.lookAt(player.x*.2,targetY+1.1,-.4);
 wife.rotation.y=Math.sin(performance.now()*.0006)*.04;sunDisc.position.y=14+Math.sin(performance.now()*.00008)*.7;
 if(player.started&&!player.finished&&Math.random()<dt*.035){tell('THE WIND IS PICKING UP')}
 renderer.render(scene,camera)}pose();updateTarget();tick();
